    if currency is not None: query = query.where(IncomingFlow.currency == currency)
    if month:
        query = query.where(func.to_char(IncomingFlow.received_date, 'YYYY-MM') == month)
    if status:
        query = query.where(IncomingFlow.match_status == status)
