@router.get("/accounts")
async def list_accounts(
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db),
    _perm=Depends(personal_finance_access("备用金管理")),
):
    """列出本仓库所有员工的备用金账户（含余额）"""
    if current_user.role == Role.SUPER_ADMIN:
        raise HTTPException(403, "超级管理员请使用各仓库管理员账号操作")
    wh_id = get_wh_id(current_user)
    # 列出所有活跃账户（排除超级管理员）
    accounts = (await db.execute(
        select(ExpenseFund).join(User, ExpenseFund.employee_id == User.id).where(
            ExpenseFund.warehouse_id.in_(get_wh_ids(current_user)),
            ExpenseFund.status == FundStatus.ACTIVE.value,
            User.role != Role.SUPER_ADMIN,
        )
    )).scalars().all()
    if getattr(current_user, '_personal_finance', False):
        accounts = [a for a in accounts if a.employee_id in current_user._personal_user_ids]
    uids = {a.employee_id for a in accounts}
    umap = {}
    if uids:
        users = (await db.execute(select(User).where(User.id.in_(uids)))).scalars().all()
        umap = {u.id: u.display_name for u in users}

    result = []
    for a in accounts:
        # 已用金额按币种分组（排除被驳回的）
        spent_q = select(ExpenseFundItem.currency, func.sum(ExpenseFundItem.amount).label("total")).where(
            ExpenseFundItem.fund_id == a.id,
            ExpenseFundItem.review_status != ReviewStatus.REJECTED.value, ExpenseFundItem.not_voided(),
        ).group_by(ExpenseFundItem.currency)
        spent_rows = (await db.execute(spent_q)).all()
        spent_by_currency = {r.currency or "THB": float(r.total or 0) for r in spent_rows}
        total_spent = round(sum(spent_by_currency.values()), 2)
        spent_regular = float((await db.execute(select(func.coalesce(func.sum(ExpenseFundItem.amount), 0)).where(
            ExpenseFundItem.fund_id == a.id, ExpenseFundItem.category != "报销",
            ExpenseFundItem.review_status != ReviewStatus.REJECTED.value, ExpenseFundItem.not_voided(),
        ))).scalar() or 0)
        result.append({
            "can_record": a.status == 'active' and (current_user.role == Role.WAREHOUSE_ADMIN or a.employee_id in await duties.identities(db, current_user)),
            "can_request": a.status == 'active' and a.employee_id == current_user.id,
            "id": a.id, "employee_id": a.employee_id,
            "employee_name": umap.get(a.employee_id, ""),
            "currency": a.currency or "THB",
