@router.get("/calendar")
async def get_calendar(
    start_date: str = None,
    end_date: str = None,
    current_user: User = Depends(employee_access(_ATTENDANCE_PERMISSION, _LEAVE_PERMISSION)),
    db: AsyncSession = Depends(get_db),
):
    if current_user.role == Role.SUPER_ADMIN:
        raise HTTPException(403, "超级管理员请使用各仓库管理员账号操作")
    if current_user.role not in (Role.WAREHOUSE_ADMIN, Role.SUPERVISOR, Role.STAFF, Role.WAREHOUSE_LABOR):
        raise HTTPException(403, "无权限")

    # 默认：当月 1 号到当天
    if start_date:
        try:
            range_start = datetime.strptime(start_date, "%Y-%m-%d").date()
        except:
            raise HTTPException(400, "开始日期格式错误 YYYY-MM-DD")
    else:
        range_start = thai_today().replace(day=1)
    if end_date:
        try:
            range_end = datetime.strptime(end_date, "%Y-%m-%d").date()
        except:
            raise HTTPException(400, "结束日期格式错误 YYYY-MM-DD")
    else:
        range_end = thai_today()
    if range_start > range_end:
        raise HTTPException(400, "开始日期不能晚于结束日期")

    wh_id = get_wh_id(current_user)
    wh_ids = get_wh_ids(current_user)

    # Get employees scoped to the active warehouse（只在职：is_deleted=False 且 status != resigned）
    emp_query = select(Employee).where(Employee.status != "resigned", Employee.is_deleted == False)
    if employee_view(current_user):
        emp_query = emp_query.where(Employee.id == current_user._attendance_employee.id, Employee.warehouse_id == wh_id)
    elif current_user.role in (Role.WAREHOUSE_ADMIN, Role.SUPERVISOR, Role.STAFF):
        # Use active (header-selected) warehouse, not all warehouses
        active_wh_id = get_wh_id(current_user)
        if active_wh_id:
            emp_query = emp_query.where(Employee.warehouse_id == active_wh_id)
        else:
            emp_query = emp_query.where(Employee.warehouse_id.in_(wh_ids))
    elif current_user.role in (Role.STAFF, Role.WAREHOUSE_LABOR):
        emp = (await db.execute(
            select(Employee.id).where(Employee.warehouse_id == wh_id, Employee.name == current_user.display_name, Employee.is_deleted == False)
        )).scalar_one_or_none()
        if emp:
            emp_query = emp_query.where(Employee.id == emp)
        else:
            return {"employees": [], "events": [], "start_date": start_date, "end_date": end_date}

    emps = (await db.execute(emp_query.order_by(Employee.name))).scalars().all()
    emp_ids = [e.id for e in emps]

    # Build employee_id <-> user_id mapping（含未绑定账号的兜底匹配：手机号=用户名 / 姓名=显示名）
    from app.services.employee_match import resolve_employee_user_map
    emp_to_user, user_to_emp = await resolve_employee_user_map(db, emps)

    # Get all clock-in records for this month, filtered by warehouse_id AND user_ids
    user_ids = list(emp_to_user.values())
    if user_ids:
        clock_records = (await db.execute(
            select(ClockInRecord).where(
                ClockInRecord.warehouse_id.in_(wh_ids),
                ClockInRecord.user_id.in_(user_ids),
                ClockInRecord.clock_date >= range_start,
                ClockInRecord.clock_date <= range_end,
            )
        )).scalars().all()
    else:
        clock_records = []
    clock_map = {}
    for cr in clock_records:
        eid = user_to_emp.get(cr.user_id)
        if eid:
            k = (eid, cr.clock_date)
            if k not in clock_map:
                clock_map[k] = []
            clock_map[k].append(cr)

    # Get leave requests (filtered by warehouse)
    leaves = (await db.execute(
        select(LeaveRequest).where(
            LeaveRequest.warehouse_id.in_(wh_ids),
            LeaveRequest.employee_id.in_(emp_ids),
            LeaveRequest.leave_date >= range_start,
            LeaveRequest.leave_date <= range_end,
            LeaveRequest.status == "approved",
        )
    )).scalars().all()
    leave_set = {(l.employee_id, l.leave_date) for l in leaves}
    # 汇总同一天所有已通过请假：full/morning/afternoon 取标记，hours 累加小时数（一天多条要相加）
    leave_map = {}
    for l in leaves:
        key = (l.employee_id, l.leave_date)
        info = leave_map.setdefault(key, {"full": False, "morning": False, "afternoon": False, "hours": 0.0, "hours_has": False})
        dt = l.duration_type or "full"
        if dt == "full":
            info["full"] = True
        elif dt == "morning":
            info["morning"] = True
        elif dt == "afternoon":
            info["afternoon"] = True
        elif dt == "hours":
            if l.hours is None:
                # 小时数为空 → 按原来的全天假处理，不报错
                info["full"] = True
                info["hourly_missing"] = True
            else:
                info["hours"] += float(l.hours)
                info["hours_has"] = True

    # Get rest days (filtered by warehouse)
    rests = (await db.execute(
        select(RestDay).where(
            RestDay.warehouse_id.in_(wh_ids),
            RestDay.employee_id.in_(emp_ids),
            RestDay.rest_date >= range_start,
            RestDay.rest_date <= range_end,
        )
    )).scalars().all()
    rest_set = {(r.employee_id, r.rest_date) for r in rests}

    # Get absences (filtered by warehouse)
    absences = (await db.execute(
        select(Absence).where(
            Absence.warehouse_id.in_(wh_ids),
            Absence.employee_id.in_(emp_ids),
            Absence.absence_date >= range_start,
            Absence.absence_date <= range_end,
        )
    )).scalars().all()
    absence_map = {(a.employee_id, a.absence_date): a for a in absences}

    # 当天应有工时（用于判断按小时请假是否够整天）
    work_sched = await get_work_schedule(db, wh_id)
    standard_hours = _standard_daily_hours(work_sched)

    # 已删除员工已在上面查询中排除，这里不再回填

    # Build calendar data
    days = []
    current = range_start
    while current <= range_end:
        day_data = {"date": current.isoformat(), "employees": {}}
        for e in emps:
            key = (e.id, current)
            # Try clock_in via employee_id matching (we need user_id mapping)
            # For now: if employee has a linked user via same name, use that
            # Actually, let me fix: ClockInRecord uses user_id not employee_id
            # We need to match employees to users. Let's do it differently.
            pass
        days.append(day_data)
        current += timedelta(days=1)

    # Better approach: return lists of events mapped by date+employee
    events = {}
    for e in emps:
        for d in range((range_end - range_start).days + 1):
            dt = range_start + timedelta(days=d)

            # Check rest / absence first（全天性质）
            session_count = 0
            has_late = False
            clock_hours = 0.0
            leave_hours_val = 0.0
            net_hourly_hours = None
            if (e.id, dt) in rest_set:
                status_name_db = "rest"
            elif (e.id, dt) in absence_map:
                status_name_db = "absent"
            else:
                sessions = clock_map.get((e.id, dt), [])
                session_set = {c.session for c in sessions}
                session_count = len(session_set)
                has_late = any(cr.status in ("late_half", "late_one") for cr in sessions)
                leave_info = leave_map.get((e.id, dt))
                morning = {1, 2}
                afternoon = {3, 4}
                has_morning = morning <= session_set
                has_afternoon = afternoon <= session_set

                # 当天打卡工时（与工资端口径一致），按小时请假时用于扣减
                sessions_by_time = sorted(sessions, key=lambda c: c.clocked_in_at or datetime.min)
                clock_hours = _clock_hours_of_day(sessions_by_time)

                status_name_db = None
                if leave_info is None:
                    pass
                elif leave_info["full"]:
                    status_name_db = "leave"
                elif leave_info["morning"]:
                    # 上午请假 + 下午打满2次卡 → 半天；否则按请假
                    status_name_db = "half" if has_afternoon else "leave"
                elif leave_info["afternoon"]:
                    # 下午请假 + 上午打满2次卡 → 半天；否则按请假
                    status_name_db = "half" if has_morning else "leave"
                elif leave_info["hours_has"]:
                    # 按小时请假：落到当天，显示「请假X小时」，工时扣减
                    leave_hours_val = round(leave_info["hours"], 2)
                    if leave_info["hours"] >= standard_hours:
                        status_name_db = "leave"  # 够整天按请假算
                    else:
                        status_name_db = "hours_leave"

                if is_hourly_leave(leave_info):
                    net_hourly_hours = hourly_leave_net_hours(
                        hourly_clock_hours(sessions_by_time), None if leave_info.get("hourly_missing") else leave_info["hours"],
                        sessions_by_time[-1].clocked_in_at if sessions_by_time else None,
                        dt, work_sched, standard_hours,
                    )

                if is_half_day_leave(leave_info):
                    leave_hours_val, net_hourly_hours = half_day_leave_hours(sessions_by_time, leave_info, dt, work_sched)

                if status_name_db is None:
                    if has_morning and has_afternoon:
                        status_name_db = "late" if has_late else "present"
                    elif session_count == 2 and (has_morning or has_afternoon):
                        # 只打满一个半天（上午或下午2次卡），另一半没请假 → 半天旷工
                        status_name_db = "half_absence"
                    elif session_count in (1, 2, 3):
                        status_name_db = "partial"
                    elif session_count == 0:
                        status_name_db = "missing" if dt <= thai_today() else "future"
                    else:
                        status_name_db = "partial"

            # Map DB names to Chinese
            status_cn = {
                "present": "正常出勤", "late": "迟到", "leave": "请假",
                "rest": "休息日", "absent": "未到", "missing": "未打卡",
                "partial": "部分打卡", "half": "半天", "half_absence": "半天旷工",
                "hours_leave": "按小时请假",
                "future": "未到"
            }
            if status_name_db == "hours_leave":
                status_label = f"请假{_fmt_hours(leave_hours_val)}小时"
            else:
                status_label = status_cn.get(status_name_db, status_name_db)
            key_str = f"{dt.isoformat()}_{e.id}"
            events[key_str] = {
                "date": dt.isoformat(),
                "employee_id": e.id,
                "employee_name": e.name,
                "status": status_name_db,
                "status_label": status_label,
                "session_count": session_count,
                "has_late": has_late,
                "leave_hours": leave_hours_val if (status_name_db == "hours_leave" or (net_hourly_hours is not None and is_half_day_leave(leave_map.get((e.id, dt))))) else None,
                "clock_hours": round(clock_hours, 2),
                "work_hours": full_day_net_hours(leave_map.get((e.id, dt)), net_hourly_hours if net_hourly_hours is not None else round(max(clock_hours - leave_hours_val, 0.0), 2)),
                "detail": "",
            }
            if (e.id, dt) in absence_map:
                events[key_str]["detail"] = absence_map[(e.id, dt)].reason or ""

    return {
        "start_date": range_start.isoformat(),
        "end_date": range_end.isoformat(),
        "employees": [{"id": e.id, "name": e.name, "position": e.position} for e in emps],
        "events": list(events.values()),
        "summary": {
            "leave_count": len(leave_set),
            "rest_count": len(rest_set),
            "absence_count": len(absences),
        }
    }

@router.get("")
async def list_overtimes(
    page: int = Query(1, ge=1),
    page_size: int = Query(50, ge=1, le=200),
    pending_verification: bool = False,
    status: str = None,
    month: str = None,  # YYYY-MM
    current_user: User = Depends(employee_access(_PERMISSION)),
    db: AsyncSession = Depends(get_db),
):
    labor_emp_id = None
    if employee_view(current_user):
        # Employees see their assigned tasks（按员工档案匹配，账号换绑也能看到）
        emp = await _find_employee_for_user(db, get_wh_id(current_user), current_user)
        if not emp:
            return {"data": [], "total": 0, "page": page, "page_size": page_size}
        labor_emp_id = emp.id
        query = (
            select(OvertimeTask)
            .join(OvertimeAssignment, OvertimeAssignment.overtime_id == OvertimeTask.id)
            .where(OvertimeAssignment.employee_id == emp.id)
            .distinct()
        )
        count_q = (
            select(func.count(func.distinct(OvertimeTask.id)))
            .join(OvertimeAssignment, OvertimeAssignment.overtime_id == OvertimeTask.id)
            .where(OvertimeAssignment.employee_id == emp.id)
        )
    else:
        wh_ids = get_wh_ids(current_user)
        query = select(OvertimeTask).where(OvertimeTask.warehouse_id.in_(wh_ids))
        count_q = select(func.count(OvertimeTask.id)).where(OvertimeTask.warehouse_id.in_(wh_ids))

    if employee_view(current_user):
        query = query.where(OvertimeTask.warehouse_id == get_wh_id(current_user))
        count_q = count_q.where(OvertimeTask.warehouse_id == get_wh_id(current_user))
    if pending_verification:
        pending = select(OvertimeAssignment.id).where(
            OvertimeAssignment.overtime_id == OvertimeTask.id, pending_overtime_assignment(),
        ).correlate(OvertimeTask).exists()
        query = query.where(pending_overtime_task(), pending)
        count_q = count_q.where(pending_overtime_task(), pending)
    if status:
        query = query.where(OvertimeTask.status == status)
        count_q = count_q.where(OvertimeTask.status == status)
    if month:
        try:
            y, m = month.split("-")
            month_start = date(int(y), int(m), 1)
            if m == "12":
                month_end = date(int(y) + 1, 1, 1)
            else:
                month_end = date(int(y), int(m) + 1, 1)
            query = query.where(OvertimeTask.date >= month_start, OvertimeTask.date < month_end)
            count_q = count_q.where(OvertimeTask.date >= month_start, OvertimeTask.date < month_end)
        except:
            pass

    total = (await db.execute(count_q)).scalar()
    result = await db.execute(
        query.order_by(OvertimeTask.created_at.desc()).offset((page - 1) * page_size).limit(page_size)
    )
    tasks = result.unique().scalars().all()

    # Collect linked user info
    creator_ids = {t.created_by for t in tasks}
    creators = {}
    if creator_ids:
        us = (await db.execute(select(User).where(User.id.in_(creator_ids)))).scalars().all()
        creators = {u.id: u.display_name for u in us}

    task_ids = [t.id for t in tasks]
    assign_map = {}
    if task_ids:
        assign_q = select(OvertimeAssignment).where(OvertimeAssignment.overtime_id.in_(task_ids))
        if pending_verification:
            assign_q = assign_q.where(pending_overtime_assignment())
        # 劳工只看得到自己那一条分配记录，管理员/主管看全部
        if labor_emp_id is not None:
            assign_q = assign_q.where(OvertimeAssignment.employee_id == labor_emp_id)
        assigns = (await db.execute(assign_q)).scalars().all()
        emp_ids = {a.employee_id for a in assigns}
        emps = {}
        emp_tpl = {}
        tpl_fee_map = {}
        if emp_ids:
            es = (await db.execute(select(Employee).where(Employee.id.in_(emp_ids)))).scalars().all()
            emps = {e.id: e.name for e in es}
            emp_tpl = {e.id: e.salary_template_id for e in es}
            tpl_ids = {e.salary_template_id for e in es if e.salary_template_id}
            if tpl_ids:
                ts = (await db.execute(select(SalaryTemplate).where(SalaryTemplate.id.in_(tpl_ids)))).scalars().all()
                tpl_fee_map = {t.id: (t.overtime_half_hour_fee or 0) for t in ts}
        for a in assigns:
            if a.overtime_id not in assign_map:
                assign_map[a.overtime_id] = []
            assign_map[a.overtime_id].append({
                "id": a.id,
                "employee_id": a.employee_id,
                "employee_name": emps.get(a.employee_id, ""),
                "confirmed": a.confirmed,
                "confirmed_at": a.confirmed_at.isoformat() if a.confirmed_at else None,
                "earned_amount": a.earned_amount,
                "actual_hours": a.actual_hours,
                "has_dispute": a.has_dispute,
                "dispute_reason": a.dispute_reason,
                "dispute_photo": a.dispute_photo,
                "overtime_half_hour_fee": tpl_fee_map.get(emp_tpl.get(a.employee_id), 0) or 0,
            })

    return {
        "data": [{
            "id": t.id,
            "warehouse_id": t.warehouse_id,
            "date": t.date.isoformat(),
            "start_time": t.start_time,
            "end_time": t.end_time,
            "hours": t.hours,
            "half_hours": _half_hours_from_times(t.start_time, t.end_time),
            "hourly_rate": t.hourly_rate,
            "status": t.status,
            "needs_verification": t.needs_verification,
            "created_by": t.created_by,
            "creator_name": creators.get(t.created_by, ""),
            "created_at": t.created_at.isoformat() if t.created_at else None,
            "assignments": assign_map.get(t.id, []),
            "total_amount": round(sum(a["earned_amount"] for a in assign_map.get(t.id, [])), 2),
            "confirmed_count": sum(1 for a in assign_map.get(t.id, []) if a["confirmed"]),
            "total_assignments": len(assign_map.get(t.id, [])),
        } for t in tasks],
        "total": total or 0,
        "page": page,
    }

@router.get("/pending")
async def pending_overtimes(
    current_user: User = Depends(employee_access(_PERMISSION, self_only=True)),
    db: AsyncSession = Depends(get_db),
):
    if not employee_view(current_user):
        raise HTTPException(403, "无权限")

    wh_id = get_wh_id(current_user)
    if not wh_id:
        return {"data": [], "pending_count": 0}

    # 先找到员工档案，再按员工档案找未确认的分配（账号换绑也能找到）
    emp = await _find_employee_for_user(db, wh_id, current_user)
    if not emp:
        return {"data": [], "pending_count": 0}

    # Find tasks where this employee has unconfirmed OR disputed assignments
    sub = (
        select(OvertimeAssignment.overtime_id)
        .where(
            OvertimeAssignment.employee_id == emp.id,
            or_(
                OvertimeAssignment.confirmed == False,
                OvertimeAssignment.has_dispute == True,
            ),
        )
        .subquery()
    )
    tasks = (await db.execute(
        select(OvertimeTask).where(
            OvertimeTask.id.in_(select(sub.c.overtime_id)),
            OvertimeTask.warehouse_id == wh_id,
        ).order_by(OvertimeTask.date.desc())
    )).scalars().all()

    # 取该员工在每个任务里的分配记录（金额 / 实际小时数 / 异议标记）
    task_ids = [t.id for t in tasks]
    assign_map = {}
    if task_ids:
        asns = (await db.execute(
            select(OvertimeAssignment).where(
                OvertimeAssignment.overtime_id.in_(task_ids),
                OvertimeAssignment.employee_id == emp.id,
            )
        )).scalars().all()
        assign_map = {a.overtime_id: a for a in asns}

    return {
        "data": [{
            "id": t.id,
            "date": t.date.isoformat(),
            "start_time": t.start_time,
            "end_time": t.end_time,
            "hours": t.hours,
            "half_hours": _half_hours_from_times(t.start_time, t.end_time),
            "needs_verification": t.needs_verification,
            "earned_amount": assign_map[t.id].earned_amount if t.id in assign_map else 0,
            "actual_hours": assign_map[t.id].actual_hours if t.id in assign_map else None,
            "has_dispute": assign_map[t.id].has_dispute if t.id in assign_map else False,
            "dispute_reason": assign_map[t.id].dispute_reason if t.id in assign_map else None,
            "hourly_rate": t.hourly_rate,
            "created_at": t.created_at.isoformat() if t.created_at else None,
        } for t in tasks],
        "pending_count": len(tasks),
    }

@router.get("/monthly-hours")
async def monthly_hours(
    month: str = None,
    current_user: User = Depends(employee_access(_PERMISSION)),
    db: AsyncSession = Depends(get_db),
):
    if month is None:
        month = thai_today().strftime("%Y-%m")

    if employee_view(current_user):
        emp = await _find_employee_for_user(db, get_wh_id(current_user), current_user)
        if not emp:
            return {"month": month, "total_hours": 0, "employee_id": None}
        hours = await _get_monthly_overtime_hours_by_employee(db, emp.id, month + "-01")
        return {"month": month, "total_hours": round(hours, 1), "employee_id": emp.id}

    wh_ids = get_wh_ids(current_user)
    y, m = month.split("-")
    month_start = date(int(y), int(m), 1)
    if m == "12":
        month_end = date(int(y) + 1, 1, 1)
    else:
        month_end = date(int(y), int(m) + 1, 1)

    rows = (await db.execute(
        select(
            OvertimeAssignment.employee_id,
            func.sum(OvertimeTask.hours).label("total_hours"),
            func.sum(OvertimeAssignment.earned_amount).label("total_amount"),
            func.count(OvertimeAssignment.id).label("task_count"),
        )
        .join(OvertimeTask, OvertimeTask.id == OvertimeAssignment.overtime_id)
        .where(
            OvertimeTask.warehouse_id.in_(wh_ids),
            OvertimeAssignment.confirmed == True,
            OvertimeTask.date >= month_start,
            OvertimeTask.date < month_end,
        )
        .group_by(OvertimeAssignment.employee_id)
    )).all()

    emp_ids = [r.employee_id for r in rows]
    emp_map = {}
    if emp_ids:
        es = (await db.execute(select(Employee).where(Employee.id.in_(emp_ids)))).scalars().all()
        emp_map = {e.id: e.name for e in es}

    return {
        "month": month,
        "data": [{
            "employee_id": r.employee_id,
            "employee_name": emp_map.get(r.employee_id, ""),
            "total_hours": round(r.total_hours or 0, 1),
            "total_amount": r.total_amount or 0,
            "task_count": r.task_count or 0,
        } for r in rows],
    }

